def do_algebra(operator, operand):
    if not operator or not operand or len(operand) < 2:
        raise ValueError("Operand must have at least two elements and operator must have at least one.")
    if len(operator) != len(operand) - 1:
        raise ValueError("The length of operator must be equal to the length of operand minus one.")

    # Build the expression string
    expr = str(operand[0])
    for i, op in enumerate(operator):
        expr += op + str(operand[i + 1])

    # Evaluate the expression
    return eval(expr)
