    end = min(interval1[1], interval2[1])

    # If there is no intersection
    if start > end:
        return "NO"

    # Calculate the length of the intersection
    length = end - start

    # Check if the length is a prime number
    if length == 0 or length == 1:
        return "NO"

    # Check for primality
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
            return False
        return True

    if is_prime(length):
        return "YES"
    else:
