        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
            return False
        return True

    def prime_factors(n):
        factors = []
        while n > 1:
            for i in range(2, n + 1):
            if n % i == 0:
                factors.append(i)
                n //= i
                break
        return factors

    factors = prime_factors(a)
    if len(factors) == 3 and all(is_prime(f) for f in factors):
        return True
    else:
        return False
