    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
            return False
        return True
    for i in range(2, a + 1):
        if a % i == 0 and is_prime(i):
            remainder = a // i
            for j in range(2, remainder + 1):
                if remainder % j == 0 and is_prime(j):
                    final_remainder = remainder // j
                    if is_prime(final_remainder):
