    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 1:
        return []

    is_prime = [False] * n
    is_prime[0] = False  # 0 is not prime
    is_prime[1] = False  # 1 is not prime
    if n > 2:
        is_prime[2] = True

    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n, i):
            is_prime[j] = False

    result = []
    for i in range(2, n):
        if is_prime[i]:
            result.append(i)

